#!/usr/bin/env python3
"""Build second verified batch of 2023 leading-firm-only candidates."""
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; WORKTABLE=ROOT/"outputs"/"涉农候选公司年份_年报主营业务复核工作表_v6.csv"; OUTPUT=ROOT/"outputs"/"2023龙头企业独有候选_年报复核第二批12家_v1.csv"
R=[
 dict(c="002329",t="2892839473.25",sn="未单列奶牛养殖收入",s="0",en="低温奶、常温奶原奶初加工",e="2000910399.03",sc="否",ec="是",bc="否",why="低温奶和常温奶合计占69.17%，按原奶初加工计入扩展口径；直接奶牛养殖收入未单列。"),
 dict(c="002385",t="33390129865.04",sn="生猪养殖、种业",s="7107538626.46",en="生猪养殖、种业、饲料、植保、疫苗、兽药",e="31629839198.29",sc="否",ec="是",bc="否",why="养猪和种业严格口径21.29%；加入农业投入品后扩展口径94.73%。"),
 dict(c="002390",t="6460841315.46",sn="无",s="0",en="医药制造与流通不属于扩展范围",e="0",sc="否",ec="否",bc="否",why="主营医药流通和制造，药品不属于农业生产、初加工、投入品或生产性服务。"),
 dict(c="002424",t="4262971440.21",sn="无",s="0",en="医药制造不属于扩展范围",e="0",sc="否",ec="否",bc="否",why="上市公司本体主营中成药等医药制造，未披露达到门槛的直接农业收入。"),
 dict(c="002431",t="4051153704.40",sn="无",s="0",en="园林工程不属于农业生产性服务",e="0",sc="否",ec="否",bc="否",why="园林施工收入占95.56%，属于工程建设和生态城镇业务，不属于农业生产性服务。"),
 dict(c="002481",t="2455941328.95",sn="无单列直接农业收入",s="0",en="食用蛋白、豌豆干淀粉、膳食纤维",e="1483932885.31",sc="否",ec="是",bc="否",why="三项豌豆初加工产品合计占60.42%，扩展口径达标；粉丝和其他收入未计入。"),
 dict(c="002507",t="2449845145.50",sn="无",s="0",en="榨菜及调味食品不属于扩展范围",e="0",sc="否",ec="否",bc="否",why="食品加工占99.84%，主要为榨菜等腌制调味食品，按普通食品/调味品规则排除。"),
 dict(c="002548",t="4040387757.83",sn="畜牧养殖",s="1143344356.53",en="畜牧养殖、饲料加工",e="3741156573.98",sc="否",ec="是",bc="否",why="养殖收入占28.30%，未达严格门槛；加入饲料后扩展口径92.59%，原料贸易未计入。"),
 dict(c="002557",t="6805627279.13",sn="无",s="0",en="休闲食品不属于扩展范围",e="0",sc="否",ec="否",bc="否",why="主营瓜子、坚果等休闲食品，按既定规则排除。"),
 dict(c="002566",t="853664904.92",sn="未单列人参种植收入",s="0",en="可识别人参类产品",e="66229313.40",sc="否",ec="否",bc="否",why="主营医药和健康食品；即使将全部人参类产品计入扩展口径也仅占7.76%，低于30%。"),
 dict(c="002567",t="26949042863.28",sn="养殖",s="5152482040.37",en="养殖、饲料",e="25209934173.12",sc="否",ec="是",bc="否",why="养殖收入占19.12%；加入饲料后扩展口径93.55%。"),
 dict(c="002582",t="1728222464.78",sn="未单列红枣种植收入",s="0",en="红枣初加工（与进一步食品加工合并披露）",e=None,sc="否",ec="待核实",bc="待核实",why="红枣制品占75.86%，但原枣初加工与进一步食品加工未可靠拆分，不能把全部红枣制品机械计入扩展口径。"),
]
def q(v,t): return None if v is None else (Decimal(v)/Decimal(t)).quantize(Decimal("0.00000001"),rounding=ROUND_HALF_UP)
def page(v):
 return str(int(v)) if isinstance(v,float) and v.is_integer() else str(v)
def main():
 d=pd.read_csv(WORKTABLE,dtype={"股票代码":str}); d=d[(d.年份==2023)&d.股票代码.isin([x["c"] for x in R])].set_index("股票代码"); assert len(d)==12; rows=[]
 for r in R:
  x=d.loc[r["c"]]; sr=q(r["s"],r["t"]); er=q(r["e"],r["t"])
  assert (sr>=Decimal("0.5"))==(r["sc"]=="是")
  if er is None: assert r["ec"]==r["bc"]=="待核实"; eligible="待核实（初加工收入无法拆分）"
  else:
   assert (er>=Decimal("0.5"))==(r["ec"]=="是") and ((Decimal("0.3")<=er<Decimal("0.5"))==(r["bc"]=="是"))
   eligible="是（严格样本）" if r["sc"]=="是" else "是（扩展样本）" if r["ec"]=="是" else "否（低于30%或不属于扩展范围）"
  rows.append({"股票代码":r["c"],"公司全称":x["公司全称"],"年份":2023,"公司营业收入_元":r["t"],"严格口径涉农业务":r["sn"],"严格口径涉农收入_元":r["s"],"严格口径涉农收入占比":f"{sr:.8f}","扩展口径涉农业务":r["en"],"扩展口径涉农收入_元":r["e"] or "","扩展口径涉农收入占比":"" if er is None else f"{er:.8f}","是否存在分部收入重叠":"按分产品或分行业同一维度；合并披露时保持待核实","严格样本结论":r["sc"],"扩展样本结论":r["ec"],"边界样本结论":r["bc"],"当年曾ST_已核实":"是" if x["当年曾ST_已核实"]=="是" else "否","最终回归样本资格_当前规则":eligible,"纳入或剔除理由":r["why"],"主营业务证据PDF页序号":page(x["年报主营业务表PDF页序号"]),"营业收入证据PDF页序号":page(x["利润表PDF页序号"]),"年报链接":x["年报链接"],"复核状态":"已人工复核（龙头独有第二批）","复核日期":"2026-08-07"})
 out=pd.DataFrame(rows); assert not out.duplicated(["股票代码","年份"]).any(); out.to_csv(OUTPUT,index=False,encoding="utf-8-sig"); print(out[["股票代码","严格口径涉农收入占比","扩展口径涉农收入占比","严格样本结论","扩展样本结论","最终回归样本资格_当前规则"]].to_string(index=False))
if __name__=="__main__": main()
